const body = $json.body ?? $json;
const action = String(body.action ?? 'quote');
const message = String(body.message ?? 'How much is scaling and polishing?').trim();
const enquiryId = String(body.enquiry_id ?? '').trim();
const date = String(body.date ?? '').trim();
const time = String(body.time ?? '').trim();
const quoteReply = String(body.quote_reply ?? '').trim();
const originalMessage = String(body.original_message ?? message).trim();
let api_url;
let payload;
if (action === 'quote') {
  api_url = 'https://n8n-production-806e.up.railway.app/webhook/favfare-demo/quote';
  payload = { message, full_name: 'Patient Demo', phone: '+2348000000200', whatsapp_id: 'favfare-sales-demo-patient' };
} else if (action === 'availability') {
  api_url = 'https://n8n-production-806e.up.railway.app/webhook/favfare-demo/booking';
  payload = { action: 'availability_for_date', preferred_date: date, enquiry_id: enquiryId };
} else {
  api_url = 'https://n8n-production-806e.up.railway.app/webhook/favfare-demo/booking';
  payload = { action: 'request_booking', enquiry_id: enquiryId, preferred_date: date, preferred_time: time };
}
return [{ json: { action, message, originalMessage, enquiry_id: enquiryId, date, time, quote_reply: quoteReply, api_url, payload } }];

const d = $json ?? {};
const c = $('Normalize Action').first().json;
const esc = (v) => String(v ?? '').replace(/[&<>\"']/g, (ch) => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[ch]));
const hidden = (name, value) => '<input type=\"hidden\" name=\"'+esc(name)+'\" value=\"'+esc(value)+'\">';
const bubble = (text, who) => '<div class=\"msg '+who+'\"><div class=\"bubble\">'+esc(text)+'</div></div>';
function nextMonday(){ const x=new Date(); const day=x.getUTCDay(); let add=(8-day)%7; if(add===0)add=7; x.setUTCDate(x.getUTCDate()+add); return x.toISOString().slice(0,10); }
function pretty(iso){ return new Date(iso+'T12:00:00Z').toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}); }
let chat = bubble('Hello 👋 Welcome to Favfare The Clinic. How may I help you today?','assistant');
let controls = '';
let heading = 'Patient Assistant';
if (c.action === 'quote') {
  chat += bubble(c.message,'patient');
  const reply = d.reply || 'I can help with that, but I need a member of the Favfare team to confirm the current price before I quote it.';
  chat += bubble(reply,'assistant');
  if (d.enquiry_id) {
    const date = nextMonday();
    controls = '<form method=\"post\" action=\"/webhook/favfare-demo/patient-action\" class=\"quickform\">'+hidden('action','availability')+hidden('enquiry_id',d.enquiry_id)+hidden('date',date)+hidden('quote_reply',reply)+hidden('original_message',c.message)+'<button>I’d like to book · check '+esc(pretty(date))+'</button></form>';
  } else { controls = '<a class=\"reset\" href=\"/webhook/favfare-demo/patient\">Try again</a>'; }
} else if (c.action === 'availability') {
  chat += bubble(c.originalMessage || 'How much is scaling and polishing?','patient');
  chat += bubble(c.quote_reply || 'Scaling and polishing is ₦25,000. Would you like to request an appointment?','assistant');
  chat += bubble('Yes, I’d like to book.','patient');
  const slots = Array.isArray(d.slots) ? d.slots.slice(0,8) : [];
  const reply = d.is_open && slots.length ? 'I found these available times for '+pretty(c.date)+'. Which works best for you?' : (d.reply || 'There are no demo slots available on that date.');
  chat += bubble(reply,'assistant');
  if (slots.length) {
    controls = '<div class=\"slots\">'+slots.map((x) => { const s=String(x).slice(0,5); return '<form method=\"post\" action=\"/webhook/favfare-demo/patient-action\">'+hidden('action','request_booking')+hidden('enquiry_id',c.enquiry_id)+hidden('date',c.date)+hidden('time',s)+hidden('quote_reply',c.quote_reply)+hidden('original_message',c.originalMessage)+'<button>'+esc(s)+'</button></form>'; }).join('')+'</div>';
  } else { controls = '<a class=\"reset\" href=\"/webhook/favfare-demo/patient\">Start over</a>'; }
} else {
  chat += bubble(c.originalMessage || 'How much is scaling and polishing?','patient');
  chat += bubble(c.quote_reply || 'Scaling and polishing is ₦25,000. Would you like to request an appointment?','assistant');
  chat += bubble('I’d like to book '+pretty(c.date)+' at '+c.time+'.','patient');
  let reply = d.reply || (d.ok ? 'Your appointment request has been recorded. A Favfare team member will confirm the booking.' : 'That slot is not available.');
  chat += bubble(reply,'assistant');
  if (d.ok) {
    chat += bubble('Your request is saved in the clinic enquiry system for staff review.','assistant');
    controls = '<div class=\"actions\"><a href=\"/webhook/favfare-demo/crm-ui\" target=\"_blank\">Open staff CRM →</a><a class=\"secondary\" href=\"/webhook/favfare-demo/patient\">New patient demo</a></div>';
  } else {
    const alt = Array.isArray(d.alternatives) ? d.alternatives.slice(0,6) : [];
    controls = alt.length ? '<div class=\"slots\">'+alt.map((x) => { const s=String(x).slice(0,5); return '<form method=\"post\" action=\"/webhook/favfare-demo/patient-action\">'+hidden('action','request_booking')+hidden('enquiry_id',c.enquiry_id)+hidden('date',c.date)+hidden('time',s)+hidden('quote_reply',c.quote_reply)+hidden('original_message',c.originalMessage)+'<button>'+esc(s)+'</button></form>'; }).join('')+'</div>' : '<a class=\"reset\" href=\"/webhook/favfare-demo/patient\">Start over</a>';
  }
}
const html='<!doctype html><html><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Favfare Patient Assistant</title><style>*{box-sizing:border-box}body{margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,sans-serif;background:#e7eee9;color:#17241e;min-height:100vh;display:grid;place-items:center;padding:22px}.wrap{width:min(1020px,100%);display:grid;grid-template-columns:1fr 390px;gap:34px;align-items:center}.intro small{font-weight:800;letter-spacing:.14em;color:#426454}.intro h1{font-size:44px;letter-spacing:-.04em;margin:10px 0}.intro p{color:#65716b;line-height:1.7;max-width:540px}.note{background:white;padding:18px;border-radius:18px;margin-top:24px;border:1px solid #d9e3dc}.phone{height:760px;max-height:90vh;background:#efeae2;border-radius:26px;overflow:hidden;box-shadow:0 24px 70px rgba(16,50,36,.22);display:flex;flex-direction:column}.top{background:#075e54;color:white;padding:14px 16px;display:flex;gap:12px;align-items:center}.avatar{width:42px;height:42px;border-radius:50%;background:white;color:#075e54;display:grid;place-items:center;font-weight:900}.top strong{display:block}.top span{font-size:12px;opacity:.8}.status{font-size:11px;padding:7px 12px;background:#fff7cf;text-align:center;color:#715800}.chat{flex:1;overflow:auto;padding:18px 14px;background-image:radial-gradient(rgba(0,0,0,.025) 1px,transparent 1px);background-size:18px 18px}.msg{display:flex;margin:9px 0}.msg.patient{justify-content:flex-end}.bubble{max-width:82%;padding:10px 12px;border-radius:9px;line-height:1.45;font-size:14px;box-shadow:0 1px 1px rgba(0,0,0,.08)}.assistant .bubble{background:white;border-top-left-radius:2px}.patient .bubble{background:#d9fdd3;border-top-right-radius:2px}.controls{padding:10px;background:#f0f2f5}.quickform button,.slots button{width:100%;border:1px solid #a9c7b8;background:white;color:#12624c;padding:11px;border-radius:12px;font-weight:800;cursor:pointer}.slots{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}.slots form{margin:0}.actions{display:grid;gap:8px}.actions a,.reset{display:block;text-align:center;text-decoration:none;background:#075e54;color:white;padding:11px;border-radius:12px;font-weight:800}.actions .secondary,.reset{background:white;color:#075e54;border:1px solid #a9c7b8}.back{display:inline-block;margin-top:16px;color:#2e5b49;font-weight:700;text-decoration:none}@media(max-width:850px){.wrap{grid-template-columns:1fr}.intro h1{font-size:34px}.phone{height:72vh}}</style></head><body><div class=\"wrap\"><section class=\"intro\"><small>BIZI SYSTEMS · LIVE SALES DEMO</small><h1>Favfare '+heading+'</h1><p>The patient-facing flow is connected to the real demo automation and enquiry CRM. Prices come from structured Favfare data; appointment requests remain pending until staff confirms them.</p><div class=\"note\"><strong>Backend status: live</strong><br><span>n8n → structured clinic data → booking rules → enquiry CRM</span></div><a class=\"back\" href=\"/webhook/favfare-demo/crm-ui\" target=\"_blank\">Open staff CRM ↗</a></section><section class=\"phone\"><div class=\"top\"><div class=\"avatar\">F</div><div><strong>Favfare The Clinic</strong><span>Patient Assistant · online</span></div></div><div class=\"status\">Demo · appointment requests require staff confirmation</div><div class=\"chat\">'+chat+'</div><div class=\"controls\">'+controls+'</div></section></div></body></html>';
return [{json:{html}}];
